target.css:
:root {
  --ink: #27352c;
  --muted: #66746a;
  --card: #fffdf7;
  --line: #d9dfcf;
  --amber: #e8a537;
  --amber-soft: #fff0c8;
  --leaf: #4f8064;
  --leaf-soft: #e3f0e6;
}

* {
  box-sizing: border-box;
}

.census-card {
  width: 480px;
  padding: 14px;
  color: var(--ink);
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 16px;
}

.card-header,
.species-row,
.card-footer,
.checklist li {
  display: flex;
  align-items: center;
}

.card-header {
  justify-content: space-between;
}

.eyebrow {
  margin: 0 0 2px;
  color: var(--leaf);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.1em;
}

h1 {
  margin: 0;
  font-size: 20px;
  line-height: 1.05;
}

.status {
  padding: 4px 8px;
  color: var(--leaf);
  background: var(--leaf-soft);
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
}

.species-row {
  gap: 9px;
  margin: 10px 0 9px;
  padding: 8px 9px;
  background: var(--amber-soft);
  border-radius: 11px;
}

.butterfly {
  font-size: 25px;
  line-height: 1;
}

figcaption {
  display: grid;
  gap: 1px;
  font-size: 12px;
}

figcaption span,
.card-footer p {
  color: var(--muted);
}

.metrics {
  display: grid;
  grid-template-columns: 1fr 1fr;
  margin: 0;
  border: 1px solid var(--line);
  border-radius: 11px;
  overflow: hidden;
}

.metrics section {
  padding: 7px 11px;
}

.metrics section + section {
  border-left: 1px solid var(--line);
}

dt {
  color: var(--muted);
  font-size: 11px;
}

dd {
  margin: 1px 0 0;
  font-size: 18px;
  font-weight: 800;
}

.checklist {
  display: grid;
  gap: 4px;
  margin: 9px 0;
  padding: 0;
  list-style: none;
  font-size: 12px;
}

.checklist li {
  gap: 6px;
}

.check {
  display: inline-grid;
  width: 16px;
  height: 16px;
  place-items: center;
  color: var(--card);
  background: var(--leaf);
  border-radius: 50%;
  font-size: 11px;
  font-weight: 800;
}

.check.pending {
  color: var(--amber);
  background: var(--amber-soft);
}

.card-footer {
  justify-content: space-between;
  padding-top: 8px;
  border-top: 1px solid var(--line);
}

.card-footer p {
  margin: 0;
  font-size: 11px;
}

button {
  padding: 6px 10px;
  color: var(--card);
  background: var(--ink);
  border: 0;
  border-radius: 7px;
  font-size: 11px;
  font-weight: 700;
}

